  <button mat-button type="button" (click)="action.emit('menu')">
    <mat-icon>home</mat-icon>
    {{ "match.actions.menu" | t }}
  </button>
  @if (onlineGuest()) {
    <p class="online-wait">{{ "match.actions.guestWaits" | t }}</p>
  } @else if (online() && !connected()) {
    <p class="online-wait">{{ "match.actions.connectionGone" | t }}</p>
  } @else if (endlessAction(); as label) {
    <button mat-flat-button type="button" (click)="action.emit('endless')">
      <mat-icon>all_inclusive</mat-icon>
      {{ label | t }}
    </button>
  } @else if (mission(); as mission) {
    @if (canChooseLevel()) {
      <button mat-stroked-button type="button" (click)="action.emit('levels')">
        <mat-icon>school</mat-icon>
        {{ "training.actions.all" | t }}
      </button>
    }
    <button mat-stroked-button type="button" (click)="action.emit('again')">
      <mat-icon>replay</mat-icon>
      {{
        (mission.done ? "match.actions.playAgain" : "match.actions.tryAgain")
          | t
      }}
    </button>
    @if (mission.next) {
      <button mat-flat-button type="button" (click)="action.emit('mission')">
        <mat-icon>skip_next</mat-icon>
        {{ "training.actions.next" | t }}
      </button>
    } @else if (mission.allDone) {
      <button mat-flat-button type="button" (click)="action.emit('campaign')">
        <mat-icon>flag</mat-icon>
        {{ "training.actions.campaign" | t }}
      </button>
    }
  } @else {
    @if (canChooseLevel() && !online()) {
      <button mat-stroked-button type="button" (click)="action.emit('levels')">
        <mat-icon>grid_view</mat-icon>
        {{ "match.actions.chooseLevel" | t }}
      </button>
    }
      if (this.hud.matchOver()) {
        untracked(() => this.finishMatch());
      }
    });
  }

  /**
   * Clears the arena after a match and, unless the player heads back to the
   * menu, kicks off the next one right away - on the following level for
   * "next level".
   */
  public onMatchEnd(action: MatchEndAction): void {
    if (action === 'next' && this.hud.upcomingLock() !== null) {
      return;
    }
    const next = action === 'next' ? this.hud.upcomingLevel() : null;
    // Where the training goes on, as the mission's result says.
    const mission =
      action === 'mission'
        ? (this.store.snapshot().earnings?.training?.next ?? null)
        : null;
    // The reset ends a match set outside the setup: a rematch sets it again.
    const rematch =
      action === 'again' ? this.gameStateService.oneMatch() : null;
    if (action === 'levels') {
      this.flow.newGameEntry.set(levelsEntry(this.flow.playKind()));
    }
    this.flow.screen.set(screenAfterMatch(action));
    if (LEAVES_PLAY.has(action)) {
      this.gameStateService.endSeries();
      this.gameStateService.leaveOnline();
    }
    this.flow
      .resetGame$()
      .pipe(
        tap(() => {
          // An online start that waited for the clear arena plays instead.
          if (this.hud.running()) {
            return;
          }
          // Only once the old arena has turned to dust: switched before, the
          // next level would flash up just to be vaporized with the old one.
          if (next != null) {
            this.gameStateService.setLevel(next.id);
          }
          if (action === 'ghost') {
